                netDebt: 145000000,
                annualEbitda: 50400000,
                quarterlyEbitda: 12600000,
                quarterlyInterest: 3073000,
                debtToEbitda: 2.88,
                interestCoverage: 4.1,
                relationship: 0,
                hedgeCost: 0,
                waiverBps: 0,
                breached: false,
                peakRatio: 2.88,
                costPts: 0,
                pending: [],
                carry: [],
                flags: {},
                qualitySum: 0,
                roundsPlayed: 0,
                totalScore: 0,
                earningsScore: 0,
                covenantScore: 0,
                cashflowScore: 0,
                costCapitalScore: 0,
                communicationScore: 0,
                covenantHistory: [],
                coverageHistory: [],
                scoreHistory: [],
                cashHistory: [],
                lastRound: null
            };
        }

        initialize(state) {
            if (!state.domainState || Object.keys(state.domainState).length === 0) {
                state.domainState = this._freshState();
            }
            if (!state.decisions || Object.keys(state.decisions).length === 0) {
                state.decisions = { decisionA: 0, decisionB: 0, decisionC: 0 };
            }
            var self = this;
            var sim = window.mySimulation;
            if (sim && sim.eventBus && typeof sim.eventBus.on === 'function' && !this._reactBound) {
                this._reactBound = true;
                sim.eventBus.on('period:undone', function(st) { self._repaint(st || sim.state); });
                sim.eventBus.on('language:changed', function() { self._repaint(sim.state); });
            }
            if (!this._docBound && typeof document !== 'undefined' && document.addEventListener) {
                this._docBound = true;
                document.addEventListener('express:langchanged', function() {
                    if (window.mySimulation && window.mySimulation.state) self._repaint(window.mySimulation.state);
                });
            }
            this._repaint(state);
        }

        _repaint(state) {
            if (!state) return;
            this._updateBriefing(state);
            this._renderRoundResult(state.domainState);
        }

        validateDecisions(decisions) {
            var selA = document.getElementById('decisionAInput');
            var selB = document.getElementById('decisionBInput');
            var selC = document.getElementById('decisionCInput');
            if (selA) decisions.decisionA = parseInt(selA.value);
            if (selB) decisions.decisionB = parseInt(selB.value);
            if (selC) decisions.decisionC = parseInt(selC.value);
            var keys = ['decisionA', 'decisionB', 'decisionC'];
            for (var i = 0; i < keys.length; i++) {
                var v = decisions[keys[i]];
                if (!v || v < 1 || v > 4) {
                    window.mySimulation.uiManager.showNotification(this._t('select_all_warning'), 'warning');
                    return false;
                }
            }
            return true;
        }

        calculateResults(state) {
            return this._computeRound(state);
        }

        // Rating of the three decisions on the five treasury dimensions (unchanged tables, unchanged weights).
        _ratings(round, d) {
            var scA = round.decisionA.scores[d.decisionA - 1];
            var scB = round.decisionB.scores[d.decisionB - 1];
            var scC = round.decisionC.scores[d.decisionC - 1];
            var avg = function(k) { return Math.round((scA[k] + scB[k] + scC[k]) / 3 * 10) / 10; };
            var r = { earnings: avg('earnings'), covenant: avg('covenant'), cashflow: avg('cashflow'),
                costCapital: avg('costCapital'), communication: avg('communication') };
            r.weighted = r.earnings * 0.25 + r.covenant * 0.25 + r.cashflow * 0.20 + r.costCapital * 0.15 + r.communication * 0.15;
            return r;
        }

        // Waiver step-up at the breach: the case and TN 5.2 put a proactive, pre-positioned waiver at a median
        // 12bp and a reactive one at 45bp. The depth of the breach adds to it.
        _waiverBps(mode, rel, ratio) {
            var depth = Math.max(0, Math.round((ratio - 3.5) * 40));
            if (mode === 'quiet') return 45 + depth + 10;
            if (mode === 'banker') return (rel >= 3 ? 22 : rel >= 1 ? 30 : 42) + depth;
            return (rel >= 3 ? 12 : rel >= 1 ? 25 : 45) + depth;
        }

        _computeRound(state) {
            var d = state.decisions;
            var ds = state.domainState;
            if (!ds.flags) {
                var base = this._freshState();
                for (var bk in base) { if (ds[bk] === undefined) ds[bk] = base[bk]; }
            }
            var rn = clamp(state.currentPeriod || 1, 1, this.ROUNDS.length);
            var round = this.ROUNDS[rn - 1];
            var rt = this._ratings(round, d);
            var m = clamp((rt.weighted - 5.5) / 2.5, -1, 1.2);
            var sh = this.SHOCKS[rn - 1];
            var mit = this.MITIGATION[rn - 1];

            var dE = sh.e + mit.e * m;
            var dCash = sh.cash + mit.cash * m;
            var dDebt = sh.debt;
            var dInt = sh.i;
            var notes = [];
            var self = this;

            // consequences of earlier rounds that land now
            var keep = [];
            (ds.pending || []).forEach(function(p) {
                if (p.r === rn) {
                    dE += p.e || 0; dCash += p.cash || 0; ds.costPts += p.costPts || 0;
                    if (p.note) notes.push(p.note);
                } else { keep.push(p); }
            });
            ds.pending = keep;
            (ds.carry || []).forEach(function(c) {
                if (rn >= c.from && rn <= c.to) { dCash += c.v; }
            });

            // a hedging programme costs every quarter after it is put on
            dE -= ds.hedgeCost;

            var letters = ['A', 'B', 'C'];
            var waiverMode = null;
            for (var li = 0; li < 3; li++) {
                var key = rn + '-' + letters[li] + '-' + d['decision' + letters[li]];
                var ef = this.EFFECTS[key];
                if (!ef) continue;
                dE += ef.e || 0; dCash += ef.cash || 0; dDebt += ef.debt || 0; dInt += ef.i || 0;
                ds.relationship += ef.rel || 0;
                if (ef.hedgeCost) { ds.hedgeCost += ef.hedgeCost; }
                if (ef.carry) { ds.carry.push({ from: ef.carryFrom, to: ef.carryTo, v: ef.carry }); dCash += (rn >= ef.carryFrom ? ef.carry : 0); }
                if (ef.later) {
                    ef.later.forEach(function(p) { ds.pending.push({ r: p.r, e: p.e || 0, cash: p.cash || 0, costPts: p.costPts || 0, note: key }); });
                }
                if (ef.flag) { ds.flags[ef.flag] = ds.flags[ef.flag] || rn; }
                if (ef.tag) { ds.flags[ef.tag] = ds.flags[ef.tag] || rn; }
                if (ef.waiver) waiverMode = ef.waiver;
            }
            ds.quarterlyEbitda = Math.round(ds.quarterlyEbitda + M(dE));
            ds.annualEbitda = ds.quarterlyEbitda * 4;
            ds.cash = Math.round(ds.cash + M(dCash));
            ds.grossDebt = Math.round(ds.grossDebt + M(dDebt));
            ds.netDebt = ds.grossDebt - ds.cash;
            ds.quarterlyInterest = Math.max(M(0.5), Math.round(ds.quarterlyInterest + M(dInt)));
            ds.debtToEbitda = ds.annualEbitda > 0 ? Math.round(ds.netDebt / ds.annualEbitda * 100) / 100 : 9.99;

            if (ds.debtToEbitda > 3.5 && !ds.breached) {
                ds.breached = true;
                ds.breachRound = rn;
                ds.waiverBps = this._waiverBps(waiverMode || 'quiet', ds.relationship, ds.debtToEbitda);
                if (!waiverMode || waiverMode === 'quiet') { ds.flags.reactive = ds.flags.reactive || rn; }
                if (ds.waiverBps >= 40) { ds.flags.cold_room = rn; }
                ds.quarterlyInterest = Math.round(ds.quarterlyInterest + ds.grossDebt * ds.waiverBps / 10000 / 4);
            }
            ds.peakRatio = Math.max(ds.peakRatio || 0, ds.debtToEbitda);
            ds.interestCoverage = Math.max(1.0, Math.round(ds.quarterlyEbitda / ds.quarterlyInterest * 100) / 100);

            var roundScore = Math.round(rt.weighted);
            ds.earningsScore += rt.earnings;
            ds.covenantScore += rt.covenant;
            ds.cashflowScore += rt.cashflow;
            ds.costCapitalScore += rt.costCapital;
            ds.communicationScore += rt.communication;
            ds.qualitySum += rt.weighted;
            ds.roundsPlayed = rn;
            ds.totalScore += roundScore;

            ds.covenantHistory.push(ds.debtToEbitda);
            ds.coverageHistory.push(ds.interestCoverage);
            ds.cashHistory.push(ds.cash);

            var sc = this._composite(ds);
            ds.scoreHistory.push(sc.overall);
            ds.processScore = sc.process;
            ds.outcomeScore = sc.outcome;
            ds.performanceTier = this._tier(sc.overall);
            ds.performance = Object.assign({}, ds.performance || {}, {
                overallScore: sc.overall, outcome: sc.outcome, process: sc.process, tier: ds.performanceTier
            });
            ds.lastRound = { r: rn, dE: Math.round(M(dE)), shockE: Math.round(M(sh.e)), dCash: Math.round(M(dCash)),
                ratio: ds.debtToEbitda, rating: Math.round(rt.weighted * 10) / 10, bps: ds.breachRound === rn ? ds.waiverBps : 0 };

            if (window.mySimulation && state === window.mySimulation.state) {
                var nextPeriod = rn + 1;
                if (nextPeriod <= this.ROUNDS.length) {
                    this._updateBriefing({ currentPeriod: nextPeriod, domainState: ds });
                } else {
                    this._updateBriefing({ currentPeriod: nextPeriod, domainState: ds });
                }
                this._renderRoundResult(ds);
            }

            return {
                period: state.currentPeriod,
                roundTitle: round.title,
                decisionA: d.decisionA,
                decisionB: d.decisionB,
                decisionC: d.decisionC,
                earningsScore: rt.earnings,
                covenantScore: rt.covenant,
                cashflowScore: rt.cashflow,
                costCapitalScore: rt.costCapital,
                communicationScore: rt.communication,
                roundScore: roundScore,
                debtToEbitda: ds.debtToEbitda,
                interestCoverage: ds.interestCoverage,
                cash: ds.cash,
                quarterlyEbitda: ds.quarterlyEbitda,
                waiverBps: ds.waiverBps,
                totalScore: ds.totalScore,
                overallScore: sc.overall,
                score: sc.overall
            };
        }

        // One function for the grade, the band, the label and the insights (G-D).
        // process: the treasury quality of the decisions (rating tables), 5.0 -> 0 and 8.0 -> 100.
        // outcome: where the decisions left Andina: covenant ratio, waiver step-up, coverage, cash, guidance credibility.
        _composite(ds) {
            var n = Math.max(1, ds.roundsPlayed || 1);
            var q = (ds.qualitySum || 0) / n;
            var process = clamp((q - 5.0) / 3.0 * 100, 0, 100);
            var ratioPts = clamp((3.9 - ds.debtToEbitda) / 0.8 * 100, 0, 100);
            var bpsPts = ds.breached ? clamp(100 - (ds.waiverBps - 10) * 2.2, 0, 100) : 100;
            var covPts = clamp((ds.interestCoverage - 2.0) / 2.0 * 100, 0, 100);
            var cashPts = clamp((ds.cash - M(15)) / M(20) * 100, 0, 100);
            var outcome = 0.40 * ratioPts + 0.25 * bpsPts + 0.20 * covPts + 0.15 * cashPts - (ds.costPts || 0) * 2;
            outcome = clamp(outcome, 0, 100);
            var overall = clamp(Math.round(0.5 * process + 0.5 * outcome), 0, 100);
            return { overall: overall, process: Math.round(process), outcome: Math.round(outcome) };
        }

        _tier(score) {
            if (score >= 80) return 'expert_cfo';
            if (score >= 65) return 'senior_cfo';
            if (score >= 50) return 'competent_treasurer';
            if (score >= 35) return 'finance_manager';
            return 'junior_analyst';
        }

        setupUI(uiManager) {
            var self = this;
            uiManager.bind('currentDay', 'currentPeriod');
            uiManager.bind('maxPeriods', 'maxPeriods');
            uiManager.bind('cashDisplay', 'domainState.cash', function(v) { return self._fmtM(v || 0); });
            uiManager.bind('debtEbitdaDisplay', 'domainState.debtToEbitda', function(v) { return self._fmtX(v, 2); });
            uiManager.bind('interestCovDisplay', 'domainState.interestCoverage', function(v) { return self._fmtX(v, 1); });
            uiManager.bind('ebitdaDisplay', 'domainState.quarterlyEbitda', function(v) { return self._fmtM(v || 0); });
            uiManager.bind('scoreDisplay', 'domainState.performance.overallScore', function(v) { return (v == null ? '-' : v) + ' / 100'; });
        }

        getChartConfig() {
            var t = window.mySimulation.t.bind(window.mySimulation);
            return {
                covenantChart: {
                    type: 'line',
                    data: {
                        labels: [],
                        datasets: [
                            { label: t('debt_ebitda_label'), data: [], borderColor: '#2c3e6b', backgroundColor: 'rgba(44,62,107,0.1)', borderWidth: 3, fill: true, tension: 0.2 },
                            { label: t('chart_covenant_limit_dataset'), data: [], borderColor: '#c0392b', borderWidth: 2, borderDash: [8, 4], fill: false, pointRadius: 0, tension: 0 }
                        ]
                    },
                    options: {
                        responsive: true,
                        maintainAspectRatio: false,
                        plugins: { title: { display: true, text: t('chart_title_covenant') } },
                        scales: {
                            y: { beginAtZero: false, suggestedMin: 2.5, suggestedMax: 4.0, title: { display: true, text: t('debt_ebitda_label') } }
                        }
                    }
                }
            };
        }

        getChartData(state) {
            var ds = (state && state.domainState) || {};
            var hist = ds.covenantHistory || [];
            var qp = this._t('q_short');
            var labels = hist.map(function(_, i) { return qp + (i + 1); });
            var covenantLine = hist.map(function() { return 3.5; });
            var canvas = document.getElementById('covenantChart');
            if (canvas && hist.length) {
                var self = this;
                canvas.setAttribute('aria-label', this._t('chart_alt') + ' ' + hist.map(function(v, i) { return self._t('q_short') + (i + 1) + ': ' + self._fmtX(v, 2); }).join(', '));
            }
            return {
                covenantChart: {
                    labels: labels,
                    datasets: [{ data: hist }, { data: covenantLine }]
                }
            };
        }

        // What the run did, read from its own history (never a play the student did not make).
        _mistakeKeys(ds) {
            var f = (ds && ds.flags) || {};
            var out = [];
            var self = this;
            ['wait_argentina', 'swap_carry', 'windfall', 'reactive', 'hedge_all'].forEach(function(k) {
                if (k === 'reactive') { if ((f.reactive || f.cold_room) && self._variant(k, ds) !== null) out.push(k); }
                else if (f[k]) out.push(k);
            });
            var when = function(k) { return k === 'reactive' ? Math.min(f.reactive || 99, f.cold_room || 99) : f[k]; };
            out.sort(function(a, b) { return when(a) - when(b); });
            return out;
        }

        // v2.1.0: which form of a mistake the run made, so the debrief says only what the student did (B12).
        // '' = the full form (or a run saved before v2.1.0, which has no tags); null = nothing to name.
        _variant(k, ds) {
            var f = (ds && ds.flags) || {};
            if (k === 'wait_argentina') return f.wait_credit && !f.wait_guidance ? '_credit' : f.wait_guidance && !f.wait_credit ? '_guidance' : '';
            if (k === 'swap_carry') return f.swap_layer && !f.swap_keep ? '_layer' : '';
            if (k === 'windfall') return f.windfall_nohedge && !f.windfall_guidance ? '_nohedge' : f.windfall_guidance && !f.windfall_nohedge ? '_guidance' : '';
            if (k === 'hedge_all') return f.hedge_mxn && !f.hedge_policy ? '_mxn' : f.hedge_policy && !f.hedge_mxn ? '_policy' : '';
            if (k === 'reactive') {
                if (!f.reactive_capex && !f.reactive_quiet) return f.cold_room || f.reactive ? (f.cold_room ? '_cold' : '') : null;
                var quiet = f.reactive_quiet && ds.breached;
                var cold = quiet || f.cold_room;
                if (f.reactive_capex) return cold ? '' : '_capex';
                return cold ? (quiet ? '_quiet' : '_cold') : null;
            }
            return '';
        }

        getPerformanceSummary(history) {
            if (!history || !history.length) return {};
            var last = history[history.length - 1];
            var ds = (last && last.domainState) || (window.mySimulation && window.mySimulation.state && window.mySimulation.state.domainState) || {};
            var sc = ds.performance && ds.performance.overallScore != null ? { overall: ds.performance.overallScore, process: ds.processScore, outcome: ds.outcomeScore } : this._composite(ds);
            var tier = this._tier(sc.overall);
            var insights = [];
            var mistakes = this._mistakeKeys(ds);
            var self = this;
            mistakes.slice(0, 3).forEach(function(k) { insights.push(self._t('mistake_' + k + self._variant(k, ds))); });
            if (ds.breached) {
                insights.push(this._t(ds.relationship >= 3 && ds.waiverBps < 30 ? 'insight_warm_waiver' : 'insight_waiver_cost').replace('{bps}', ds.waiverBps));
            } else {
                insights.push(this._t('insight_no_breach'));
            }
            if (!mistakes.length) insights.push(this._t('insight_architecture_held'));
            insights.push(this._t('insight_final_ratio').replace('{ratio}', this._fmtX(ds.debtToEbitda, 2)).replace('{peak}', this._fmtX(ds.peakRatio, 2)));
            return {
                totalScore: sc.overall,
                overallScore: sc.overall,
                composite: sc.overall,
                score: sc.overall,
                outcomeScore: sc.outcome,
                processScore: sc.process,
                maxPossible: 100,
                percentage: sc.overall,
                performance: tier,
                performanceKey: 'perf_' + tier,
                performanceLabel: this._t('perf_' + tier),
                finalRatio: ds.debtToEbitda,
                waiverBps: ds.waiverBps || 0,
                mistakes: mistakes,
                turningKey: mistakes.length ? 'turning_' + mistakes[0] + this._variant(mistakes[0], ds) : 'turning_none',
                insights: insights.slice(0, 5)
            };
        }

        formatCompletionMessage(summary) {
            if (!summary || summary.overallScore == null) return '';
            var self = this;
            var ds = (window.mySimulation && window.mySimulation.state && window.mySimulation.state.domainState) || {};
            var esc = function(s) { return String(s).split('&').join('&amp;').split('<').join('&lt;').split('>').join('&gt;'); };
            var turning = this._t(summary.turningKey || (summary.mistakes && summary.mistakes.length ? 'turning_' + summary.mistakes[0] : 'turning_none'));
            var h = '<div class="cfo-cm">';
            h += '<div class="cfo-cm-score"><strong>' + summary.overallScore + '/100</strong> &middot; ' + esc(this._t('perf_' + summary.performance)) + '</div>';
            h += '<ul class="cfo-cm-kpis">';
            h += '<li>' + esc(this._t('cm_outcome')) + ': ' + summary.outcomeScore + '/100</li>';
            h += '<li>' + esc(this._t('cm_process')) + ': ' + summary.processScore + '/100</li>';
            h += '<li>' + esc(this._t('debt_ebitda_label')) + ': ' + this._fmtX(summary.finalRatio, 2) + '</li>';
            h += '<li>' + esc(this._t('cm_waiver')) + ': ' + (ds.breached ? summary.waiverBps + ' bp' : esc(this._t('cm_no_breach'))) + '</li>';
            h += '</ul>';
            h += '<h4>' + esc(this._t('cm_turning')) + '</h4><p>' + esc(turning) + '</p>';
            h += '<h4>' + esc(this._t('cm_insights')) + '</h4><ul>';
            (summary.insights || []).forEach(function(s) { h += '<li>' + esc(s) + '</li>'; });
            h += '</ul><h4>' + esc(this._t('cm_questions')) + '</h4><ol>';
            ['cm_q1', 'cm_q2', 'cm_q3'].forEach(function(k) { h += '<li>' + esc(self._t(k)) + '</li>'; });
            h += '</ol></div>';
            return h;
        }

        getHint(state, results) {
            if (!results) return null;
            if (results.debtToEbitda > 3.5) return this._t('hint_covenant_breach');
            if (results.debtToEbitda > 3.2) return this._t('hint_covenant_warning');
            if (results.interestCoverage < 3.0) return this._t('hint_coverage_low');
            return null;
        }

        getHistoryTableConfig() {
            var self = this;
            return [
                { key: 'results.roundTitle', label: 'Quarter', i18nKey: 'col_quarter', formatter: function(v) { var R = self.ROUNDS.filter(function(x) { return x.title === v; })[0]; return R && self._lang() === 'es' ? R.titleEs : v; } },
                { key: 'results.overallScore', label: 'Score', i18nKey: 'col_score' },
                { key: 'results.debtToEbitda', label: 'Debt/EBITDA', i18nKey: 'col_debt_ebitda', formatter: function(v) { return self._fmtX(v || 0, 2); } },
                { key: 'results.interestCoverage', label: 'Int. Coverage', i18nKey: 'col_coverage', formatter: function(v) { return self._fmtX(v || 0, 1); } },
                { key: 'results.cash', label: 'Cash', i18nKey: 'col_cash', formatter: function(v) { return self._fmtM(v || 0); } }
            ];
        }

        getPresets() { return null; }

        _renderRoundResult(ds) {
            var el = document.getElementById('cfoRoundResult');
            if (!el) return;
            var lr = ds && ds.lastRound;
            if (!lr) { el.innerHTML = ''; el.style.display = 'none'; return; }
            el.style.display = '';
            var rel = ds.relationship >= 3 ? 'rel_warm' : ds.relationship >= 1 ? 'rel_neutral' : 'rel_cold';
            var h = '<h3>' + this._t('result_heading').replace('{n}', lr.r) + '</h3><ul>';
            h += '<li>' + this._t('result_ebitda').replace('{shock}', this._fmtM(lr.shockE)).replace('{net}', this._fmtM(lr.dE)) + '</li>';
            h += '<li>' + this._t('result_cash').replace('{cash}', this._fmtM(lr.dCash)) + '</li>';
            h += '<li>' + this._t('result_ratio').replace('{ratio}', this._fmtX(lr.ratio, 2)) + '</li>';
            h += '<li>' + this._t('result_rel') + ' ' + this._t(rel) + '</li>';
            if (ds.hedgeCost > 0) h += '<li>' + this._t('result_hedgecost').replace('{v}', this._fmtM(ds.hedgeCost * 1000000)) + '</li>';
            if (lr.bps) h += '<li><strong>' + this._t('result_waiver').replace('{bps}', lr.bps) + '</strong></li>';
            h += '</ul>';
            el.innerHTML = h;
        }

        _updateBriefing(state) {
            var n = state.currentPeriod || 1;
            var lang = this._lang();
            var isEs = lang === 'es';
            var controls = document.querySelector('.cfo-sim-controls');
            var briefEl = document.getElementById('briefingText');
            var briefTitle = document.getElementById('briefingTitle');
            if (n > this.ROUNDS.length) {
                if (controls) controls.style.display = 'none';
                if (briefTitle) briefTitle.textContent = this._t('end_title');
                if (briefEl) briefEl.innerHTML = this._t('end_text');
                return;
            }
            if (controls) controls.style.display = '';
            var canvas = document.getElementById('covenantChart');
            if (canvas && canvas.setAttribute && !((state.domainState || {}).covenantHistory || []).length) {
                canvas.setAttribute('aria-label', this._t('chart_alt'));
            }
            var idx = n - 1;
            var round = this.ROUNDS[idx];
            var ds = state.domainState || (window.mySimulation && window.mySimulation.state && window.mySimulation.state.domainState) || {};
            var ratio = this._fmtX(ds.debtToEbitda || 2.88, 2);
            if (briefEl) {
                briefEl.innerHTML = (isEs ? round.briefingEs : round.briefing).split('{ratio}').join(ratio);
            }
            if (briefTitle) {
                briefTitle.textContent = isEs ? round.titleEs : round.title;
            }

            var labelA = document.getElementById('labelDecA');
            var labelB = document.getElementById('labelDecB');
            var labelC = document.getElementById('labelDecC');
            if (labelA) labelA.textContent = isEs ? round.decisionA.labelEs : round.decisionA.label;
            if (labelB) labelB.textContent = isEs ? round.decisionB.labelEs : round.decisionB.label;
            if (labelC) labelC.textContent = isEs ? round.decisionC.labelEs : round.decisionC.label;

            var placeholder = this._t('select_option');
            var ord = this.OPTION_ORDER[idx] || [];
            var shown = function(order, k) {
                return (order && order.length === k) ? order : Array.apply(null, Array(k)).map(function(x, m) { return m + 1; });
            };
            var fill = function(sel, dec, order) {
                if (!sel) return;
                var prev = sel.value;
                sel.innerHTML = '<option value="">' + placeholder + '</option>';
                var opts = isEs ? dec.optionsEs : dec.options;
                var oo = shown(order, opts.length);
                for (var i = 0; i < oo.length; i++) {
                    sel.innerHTML += '<option value="' + oo[i] + '">' + String.fromCharCode(65 + i) + ') ' + opts[oo[i] - 1] + '</option>';
                }
                if (prev && sel.__cfoRound === n) sel.value = prev;
                sel.__cfoRound = n;
            };
            fill(document.getElementById('decisionAInput'), round.decisionA, ord[0]);
            fill(document.getElementById('decisionBInput'), round.decisionB, ord[1]);
            fill(document.getElementById('decisionCInput'), round.decisionC, ord[2]);
        }

